"use client";

import { useEffect } from "react";
import { analytics } from "@/lib/analytics";

interface NewsTrackerProps {
  articleId: string;
  slug?: string | null;
  category?: string;
}

export default function NewsTracker({ articleId, slug, category }: NewsTrackerProps) {
  useEffect(() => {
    analytics.newsArticleView(articleId, slug || undefined, category);
  }, [articleId, slug, category]);

  return null;
}
